// TAQO — общие шаги приглашений: форма /users/invite, баннер «קישור ההצטרפות (מוצג פעם אחת)» на /users,
// «ביטול הזמנה» через окно подтверждения (#db7e39: «חזרה» / «ביטול ההזמנה»), очистка приглашений автотестов.
// Факты проверки 14.11.2026 (бандл после fdbef3f): ссылка в баннере — только `/accept?token=<hex>` (#83bf5b),
// окно отмены — заголовок «ביטול הזמנה», текст «לבטל את ההזמנה של <имя>? קישור ההצטרפות שנשלח יפסיק לעבוד.»,
// кнопки «חזרה» и «ביטול ההזמנה».
import { Page, Locator, expect } from '@playwright/test';

export const INVITE_PATH = '/users/invite';
export const SAVE_INVITE = 'שמירה והזמנה';
export const CANCEL_INVITE = 'ביטול הזמנה';
export const CONFIRM_CANCEL = 'ביטול ההזמנה';
export const DIALOG_BACK = 'חזרה';
export const PENDING = 'הזמנה ממתינה';
export const BANNER_TEXT = 'שלחו לו את קישור ההצטרפות (מוצג פעם אחת)';
export const LINK_RE = /https?:\/\/\S+\/accept\?token=\S+/;

export const inviteHeading = (page: Page) => page.getByRole('heading', { name: 'הזמנת משתמש חדש', level: 1 });
export const nameField = (page: Page) => page.getByLabel(/שם מלא/);
export const emailField = (page: Page) => page.getByLabel(/^אימייל/);
export const saveButton = (page: Page) => page.getByRole('button', { name: SAVE_INVITE, exact: true });
export const usersHeading = (page: Page) => page.getByRole('heading', { name: 'משתמשי החברה', level: 1 });
export const rowOf = (page: Page, email: string) => page.getByRole('row').filter({ hasText: email });

/** Баннер со ссылкой: текст «…קישור ההצטרפות (מוצג פעם אחת)» и сама ссылка /accept?token=. */
export const bannerText = (page: Page) => page.getByText(BANNER_TEXT);
export const bannerLink = (page: Page) => page.getByText(/\/accept\?token=/);

/** Окно подтверждения отмены приглашения (роль dialog или alertdialog). */
export const cancelDialog = (page: Page): Locator =>
  page.getByRole('alertdialog').or(page.getByRole('dialog')).filter({ hasText: CANCEL_INVITE });

/** Открыть форму приглашения. */
export async function openInvite(page: Page) {
  await page.goto(INVITE_PATH);
  await expect(inviteHeading(page)).toBeVisible();
}

/** Заполнить форму и нажать «שמירה והזמנה» (без проверки результата). */
export async function submitInvite(page: Page, name: string, email: string) {
  await nameField(page).fill(name);
  await emailField(page).fill(email);
  await saveButton(page).click();
}

/** Пригласить (роль по умолчанию — משתמש רגיל): возврат на /users, строка «הזמנה ממתינה». */
export async function invite(page: Page, name: string, email: string) {
  await openInvite(page);
  await submitInvite(page, name, email);
  await expect(page).toHaveURL(/\/users(\?|$)/);
  await expect(rowOf(page, email).first()).toContainText(PENDING);
}

/**
 * Ссылка из баннера на /users. При повторном приглашении (previous) — ждём новую, отличную от прежней.
 * Формат после #83bf5b: только token, без email/name/company/inviter.
 */
export async function readBannerLink(page: Page, previous?: string): Promise<string> {
  let link = '';
  await expect
    .poll(
      async () => {
        const text = (await bannerLink(page).first().textContent().catch(() => '')) ?? '';
        link = text.match(LINK_RE)?.[0] ?? '';
        return link !== '' && link !== previous;
      },
      { message: 'в баннере нет (новой) ссылки /accept?token=' },
    )
    .toBe(true);
  return link;
}

/** «ביטול הזמנה» в строке приглашения → открыто окно подтверждения. */
export async function openCancelDialog(page: Page, email: string): Promise<Locator> {
  await rowOf(page, email).first().getByRole('button', { name: CANCEL_INVITE, exact: true }).click();
  const dialog = cancelDialog(page);
  await expect(dialog).toBeVisible();
  return dialog;
}

/** Отменить приглашение с подтверждением; строка исчезает. */
export async function cancelInviteConfirmed(page: Page, email: string) {
  const dialog = await openCancelDialog(page, email);
  await dialog.getByRole('button', { name: CONFIRM_CANCEL, exact: true }).click();
  await expect(dialog).toBeHidden();
  await expect(rowOf(page, email)).toHaveCount(0);
}

/**
 * Очистка: на /users отменить (с подтверждением) все приглашения, строки которых совпадают с pattern
 * (в т.ч. оставшиеся от упавших прогонов). Активных участников не трогает.
 */
export async function cancelAllInvites(page: Page, pattern: RegExp) {
  await page.goto('/users');
  await expect(usersHeading(page)).toBeVisible();
  await expect(page.getByRole('row').filter({ hasText: 'פעיל' }).first()).toBeVisible();
  const rows = page.getByRole('row').filter({ hasText: pattern });
  for (let n = await rows.count(); n > 0; n = await rows.count()) {
    await rows.first().getByRole('button', { name: CANCEL_INVITE, exact: true }).click();
    const dialog = cancelDialog(page);
    await expect(dialog).toBeVisible();
    await dialog.getByRole('button', { name: CONFIRM_CANCEL, exact: true }).click();
    await expect(dialog).toBeHidden();
    await expect(rows).toHaveCount(n - 1);
  }
}
